import unittest
from solution import count_occurrences

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(count_occurrences("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(count_occurrences("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(count_occurrences(""), {})
    def test_punct(self):
        self.assertEqual(count_occurrences("a, a,"), {"a,": 2})
